package limiter

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time so tests can inject a fake.
type Clock interface {
	Now() time.Time
}

// realClock uses the standard library.
type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
// Tokens refill continuously at rate tokens per second, up to capacity.
type Limiter struct {
	mu       sync.Mutex
	tokens   float64
	capacity float64
	rate     float64 // tokens per second
	last     time.Time
	clock    Clock
}

// ErrInvalidConfig is returned by New for bad parameters.
var ErrInvalidConfig = errors.New("limiter: capacity and rate must be > 0")

// New creates a Limiter with the given burst capacity and refill rate
// (tokens per second), starting full.
func New(capacity, rate float64) (*Limiter, error) {
	return NewWithClock(capacity, rate, realClock{})
}

// NewWithClock is New with an injectable clock.
func NewWithClock(capacity, rate float64, clock Clock) (*Limiter, error) {
	if capacity <= 0 || rate <= 0 {
		return nil, ErrInvalidConfig
	}
	if clock == nil {
		clock = realClock{}
	}
	now := clock.Now()
	return &Limiter{
		tokens:   capacity,
		capacity: capacity,
		rate:     rate,
		last:     now,
		clock:    clock,
	}, nil
}

// Allow reports whether a single token is available.
func (l *Limiter) Allow() bool {
	return l.AllowN(1)
}

// AllowN reports whether n tokens are available, consuming them if so.
func (l *Limiter) AllowN(n float64) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	elapsed := now.Sub(l.last).Seconds()
	l.last = now
	l.tokens += elapsed * l.rate
	if l.tokens > l.capacity {
		l.tokens = l.capacity
	}
	if l.tokens >= n {
		l.tokens -= n
		return true
	}
	return false
}

// Tokens returns the current number of available tokens (for tests/monitoring).
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	now := l.clock.Now()
	l.tokens += now.Sub(l.last).Seconds() * l.rate
	l.last = now
	if l.tokens > l.capacity {
		l.tokens = l.capacity
	}
	return l.tokens
}
