	if got := l.RetryAfter(1); got != time.Second {
		t.Errorf("RetryAfter = %v, want %v", got, time.Second)
	}
	// RetryAfter must not consume tokens.
	if got := l.RetryAfter(1); got != time.Second {
		t.Errorf("RetryAfter again = %v, want %v", got, time.Second)
	}
	fc.Advance(time.Second)
	if got := l.RetryAfter(1); got != 0 {
		t.Errorf("RetryAfter after refill = %v, want 0", got)
	}
